-- A sprint folder is a normal folder with settings (PROVEN: PUT /hierarchy/v2/category/{id}/sprint). Sprint folders at space level only is ASSUMED (a template apply into another folder returned 400, the rule behind it is unconfirmed).
CREATE TABLE sprint_folder_settings (
  folder_id                    uuid PRIMARY KEY /* id -> hierarchy.folders */,
  workspace_id                 uuid NOT NULL /* id -> access.workspaces */,
  name_format                  text NOT NULL DEFAULT 'Sprint {INDEX} ({START_DATE} - {END_DATE})',  -- PROVEN, {INDEX} required
  date_format                  text NOT NULL DEFAULT 'm/d',            -- PROVEN
  start_day                    smallint NOT NULL DEFAULT 1 CHECK (start_day BETWEEN 0 AND 6),     -- PROVEN 1 = Monday
  estimation                   text NOT NULL DEFAULT 'points' CHECK (estimation IN ('points','tasks','time_estimate')), -- 'points' PROVEN, rest ASSUMED
  capacity                     numeric(10,2) NOT NULL DEFAULT 50,      -- PROVEN
  duration_number              integer NOT NULL DEFAULT 2 CHECK (duration_number > 0),
  duration_timeframe           text NOT NULL DEFAULT 'weeks' CHECK (duration_timeframe IN ('days','weeks')),  -- 'weeks' PROVEN
  non_working_days             smallint[] NOT NULL DEFAULT '{0,6}',    -- PROVEN
  timezone                     text NOT NULL DEFAULT 'UTC',            -- PROVEN
  start_time_offset            integer NOT NULL DEFAULT 0,             -- PROVEN
  close_past_sprints           boolean NOT NULL DEFAULT true,          -- PROVEN "when sprint ends mark done"
  spillover_tasks              boolean NOT NULL DEFAULT false,         -- PROVEN "move incomplete tasks to next sprint"
  create_new_sprints           boolean NOT NULL DEFAULT false,         -- PROVEN
  num_future_sprints           integer NOT NULL DEFAULT 1,             -- PROVEN
  archive_old_sprints          boolean NOT NULL DEFAULT false,         -- PROVEN
  archive_threshold            integer,                                -- PROVEN "keep most recent N"
  auto_lock_forecast_at_start  boolean NOT NULL DEFAULT false,         -- PROVEN
  auto_create_dashboard_view   boolean NOT NULL DEFAULT true,          -- PROVEN
  default_list_template_id     uuid /* id -> tasks.templates */,          -- PROVEN subcategory_template_id
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  version                      integer NOT NULL DEFAULT 1
);

-- A sprint IS a list (PROVEN: subcategory with sprint:true). This row adds the sprint-only columns.
CREATE TABLE sprints (
  list_id            uuid PRIMARY KEY /* id -> hierarchy.lists */,
  workspace_id       uuid NOT NULL /* id -> access.workspaces */,
  folder_id          uuid NOT NULL /* id -> hierarchy.folders */,
  sprint_index       integer NOT NULL,                                  -- PROVEN, sequential from 1
  start_at           timestamptz NOT NULL,                              -- PROVEN epoch ms
  end_at             timestamptz NOT NULL,                              -- PROVEN, end of day 23:59:59.999
  status             text NOT NULL DEFAULT 'not_started' CHECK (status IN ('not_started','active','done')),  -- 'Not started' PROVEN label; rest ASSUMED
  forecast_locked_at timestamptz,                                       -- ASSUMED, manual or auto lock (PROVEN options)
  forecast_value     numeric(10,2),                                     -- ASSUMED, effort at lock time
  done_at            timestamptz,
  CHECK (end_at > start_at),
  UNIQUE (folder_id, sprint_index)
);

CREATE INDEX sprints_active_idx ON sprints (workspace_id, status, end_at);

-- worker: "which sprints end now"
CREATE INDEX sprints_folder_idx ON sprints (workspace_id, folder_id, start_at);

-- sprint folder page

-- ASSUMED: nightly snapshot per sprint for burndown/velocity so charts do not rescan task history.
CREATE TABLE sprint_daily_stats (
  list_id      uuid NOT NULL REFERENCES sprints(list_id) ON DELETE CASCADE,
  day          date NOT NULL,
  total_effort numeric(10,2) NOT NULL,
  done_effort  numeric(10,2) NOT NULL,
  tasks_total  integer NOT NULL,
  tasks_done   integer NOT NULL,
  PRIMARY KEY (list_id, day)
);

-- Sprint Points ClickApp (PROVEN: enabled per space, point values 1 2 3 5 8, rollup to parents, points per assignee).
CREATE TABLE space_sprint_points (
  space_id         uuid PRIMARY KEY /* id -> hierarchy.spaces */,
  workspace_id     uuid NOT NULL /* id -> access.workspaces */,
  point_values     numeric[] NOT NULL DEFAULT '{1,2,3,5,8}',
  rollup_to_parent boolean NOT NULL DEFAULT false,
  per_assignee     boolean NOT NULL DEFAULT false
);

-- ===== NEW for the split: tasks in sprint lists, for capacity, burndown and close/rollover
CREATE TABLE sprint_task_copies (
  task_id         uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL,
  list_id         uuid NOT NULL,                     -- the sprint list (home or extra membership)
  in_list_ids     uuid[] NOT NULL,                   -- every list the task is in
  status_category text NOT NULL,
  points          numeric(10,2),
  time_estimate_ms bigint,
  assignee_ids    uuid[] NOT NULL DEFAULT '{}',
  done_at         timestamptz,
  deleted         boolean NOT NULL DEFAULT false,
  source_version  integer NOT NULL
);
CREATE INDEX sprint_task_copies_list_idx ON sprint_task_copies (workspace_id, list_id);
CREATE INDEX sprint_task_copies_in_list_gin ON sprint_task_copies USING gin (in_list_ids);
